def normalize_word(word):
    return word.lower()


def split_into_words(text):
    return text.split()


def remove_punctuation(word):
    import string
    return word.strip(string.punctuation)


def count_words(words):
    frequency = {}
    for word in words:
        frequency[word] = frequency.get(word, 0) + 1
    return frequency


def process_text_to_words(text):
    words = split_into_words(text)
    cleaned_words = [remove_punctuation(word) for word in words]
    normalized_words = [normalize_word(word) for word in cleaned_words if word]
    return normalized_words


def word_frequency(text):
    processed_words = process_text_to_words(text)
    return count_words(processed_words)

