    counts = {}
    for char in text.lower():
        if char.isalpha():
            counts[char] = counts.get(char, 0) + 1
    return counts


def get_ordered_unique_chars(text):
    seen = set()
    ordered = []
    for char in text.lower():
        if char.isalpha() and char not in seen:
            ordered.append(char)
            seen.add(char)
    return ordered


