def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    return _process_string(s, stack, mapping)


def _process_string(s: str, stack: list, mapping: dict) -> bool:
    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            return False # Handle unexpected characters

    return _check_final_stack(stack)


def _check_final_stack(stack: list) -> bool:
    return not stack


