def _handle_base_cases(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    return None


def _initialize_memoization_table(n):
    return [-1] * (n + 1)


def _populate_initial_values(memo):
    memo[0] = 0
    memo[1] = 1


def _calculate_fibonacci_iteratively(n, memo):
    for i in range(2, n + 1):
        memo[i] = memo[i - 1] + memo[i - 2]
    return memo[n]


def nth_fibonacci(n):
    base_result = _handle_base_cases(n)
    if base_result is not None:
        return base_result

    memo = _initialize_memoization_table(n)
    _populate_initial_values(memo)
    return _calculate_fibonacci_iteratively(n, memo)


def run_tests():
    assert nth_fibonacci(0) == 0
    assert nth_fibonacci(1) == 1
    assert nth_fibonacci(2) == 1
