def decrypt_caesar(text, shift):
    decrypted_chars = []
    for char in text:
        decrypted_char = _decrypt_char(char, shift)
        decrypted_chars.append(decrypted_char)
    return "".join(decrypted_chars)


def _decrypt_char(char, shift):
    if not _is_lowercase_alpha(char):
        return char
    return _shift_char(char, shift)


def _is_lowercase_alpha(char):
    return 'a' <= char <= 'z'


def _shift_char(char, shift):
    start = ord('a')
    end = ord('z')
    shifted_ord = ord(char) - shift
    return chr(_wrap_around(shifted_ord, start, end))


def _wrap_around(val, start, end):
    range_size = end - start + 1
    return start + (val - start) % range_size


def _test_decryption():
    assert decrypt_caesar('khoor', 3) == 'hello'
    assert decrypt_caesar('wkhuh', 3) == 'there'
    assert decrypt_caesar('abc', 0) == 'abc'
    assert decrypt_caesar('xyz', 1) == 'wxy'
    assert decrypt_caesar('abc', 26) == 'abc'
    assert decrypt_caesar('abc', 27) == 'zab'

_test_decryption()

