import random


def generate_pin(length):
    """Generates a random numeric PIN of the specified length."""
    return _generate_random_digits(length)


def _generate_random_digits(length):
    """Helper to generate a string of random digits."""
    digits = []
    for _ in range(length):
        digits.append(_get_random_digit())
    return "".join(digits)


def _get_random_digit():
    """Returns a single random digit as a string."""
    return str(random.randint(0, 9))


def _validate_length(length):
    """Ensures the length is a positive integer."""
    if not isinstance(length, int) or length <= 0:
        raise ValueError("Length must be a positive integer.")


def _convert_to_string(digits_list):
