def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = get_bracket_mapping()
    open_brackets = get_open_brackets()

    for char in s:
        if is_open_bracket(char, open_brackets):
            stack.append(char)
        else:
            if not stack:
                return False
            top_element = stack.pop()
            if not matches_pair(top_element, char, mapping):
                return False

    return not stack


