def get_start_time(meeting):
    return meeting[0]


def get_end_time(meeting):
    return meeting[1]


def is_start_before_end(meeting):
    return get_start_time(meeting) < get_end_time(meeting)


def is_point_in_interval(point, interval):
    return get_start_time(interval) < point < get_end_time(interval)


def check_overlap_direction(meeting1, meeting2):
    return is_point_in_interval(get_start_time(meeting2), meeting1) or \
           is_point_in_interval(get_end_time(meeting2), meeting1)


def has_overlap(meeting1, meeting2):
    if not is_start_before_end(meeting1) or not is_start_before_end(meeting2):
        raise ValueError("Meeting start time must be before end time.")

    return check_overlap_direction(meeting1, meeting2) or \
           check_overlap_direction(meeting2, meeting1) or \
           (get_start_time(meeting1) <= get_start_time(meeting2) and get_end_time(meeting1) >= get_end_time(meeting2))

