    max_count = find_max_count(counts)
    mode = get_mode_value(counts, max_count)
    return mode

def count_occurrences(numbers_list):
    return Counter(numbers_list)

def find_max_count(counts_dict):
    if not counts_dict:
        return 0
    return max(counts_dict.values())

def get_mode_value(counts_dict, max_val):
    for number, count in counts_dict.items():
        if count == max_val:
            return number
    return None

def main():
    print(calculate_mode([1, 2, 2, 3, 3, 3, 4]))
    print(calculate_mode([5, 5, 1, 1]))

if __name__ == "__main__":
