import math


def get_divisors(number):
    divs = set()
    for i in range(1, int(math.sqrt(number)) + 1):
        if number % i == 0:
            divs.add(i)
            divs.add(number // i)
    return sorted(list(divs))


def get_proper_divisors(number):
    all_divisors = get_divisors(number)
    return [d for d in all_divisors if d != number]


def sum_divisors(divisors):
    return sum(divisors)


def is_equal_to_number(s, number):
    return s == number


def is_perfect_number(number):
    if number <= 0:
        return False
    proper_divs = get_proper_divisors(number)
    sum_of_proper_divisors = sum_divisors(proper_divs)
    return is_equal_to_number(sum_of_proper_divisors, number)


def main():
    print(is_perfect_number(6))
    print(is_perfect_number(28))
