def calculate_mean(numbers):
    if not numbers:
        return 0.0
    return sum(numbers) / len(numbers)


def calculate_absolute_deviations(numbers, mean):
    return [abs(x - mean) for x in numbers]


def calculate_sum_of_deviations(deviations):
    return sum(deviations)


def calculate_average_deviation(total_deviation, count):
    if count == 0:
        return 0.0
    return total_deviation / count


def mean_absolute_deviation(numbers):
    if not numbers:
        return 0.0

    mean = calculate_mean(numbers)
    deviations = calculate_absolute_deviations(numbers, mean)
    total_deviation = calculate_sum_of_deviations(deviations)

    return calculate_average_deviation(total_deviation, len(numbers))

