import math


def is_valid_triangle(a: float, b: float, c: float) -> bool:
    """Checks if three side lengths can form a valid triangle."""
    return a + b > c and a + c > b and b + c > a and a > 0 and b > 0 and c > 0


def calculate_semi_perimeter(a: float, b: float, c: float) -> float:
    """Calculates the semi-perimeter of a triangle."""
    return (a + b + c) / 2


def apply_herons_formula(s: float, a: float, b: float, c: float) -> float:
    """Applies Heron's formula to calculate the area."""
    return math.sqrt(s * (s - a) * (s - b) * (s - c))


def triangle_area(a: float, b: float, c: float) -> float:
    """Calculates the area of a triangle given its side lengths."""
    if not is_valid_triangle(a, b, c):
        return 0.0
    s = calculate_semi_perimeter(a, b, c)
    area = apply_herons_formula(s, a, b, c)
    return area


