def get_digit_char(value):
    if 0 <= value <= 9:
        return str(value)
    elif 10 <= value <= 15:
        return chr(ord('A') + value - 10)
    else:
        raise ValueError("Digit value out of range")


def convert_single_digit(remainder):
    return get_digit_char(remainder)


def calculate_remainder_and_quotient(number, base):
    return number % base, number // base


