def count_set_bits(n):
    """Counts the number of set bits (1s) in the binary representation of a non-negative integer."""
    if not_negative(n):
        return calculate_bits(n)
    else:
        raise ValueError("Input must be a non-negative integer.")


def not_negative(n):
    """Checks if the input integer is non-negative."""
    return n >= 0


def calculate_bits(n):
    """Performs the bit counting logic."""
    count = 0
    while n > 0:
        n = clear_lowest_set_bit(n)
        count = increment_count(count)
    return count


def clear_lowest_set_bit(n):
    """Clears the lowest set bit in the number using n & (n-1)."""
    return n & (n - 1)


def increment_count(count):
    """Increments the count by one."""
    return count + 1


